let scrollFallback;document$.subscribe(()=>{const previousOverlay=document.querySelector('.section-flash-overlay',);if(previousOverlay){previousOverlay.classList.remove('is-visible');previousOverlay.removeAttribute('style');}
const content=document.querySelector('.md-content__inner');if(!content){return;}
let outline=document.querySelector('.section-flash-overlay');if(!outline){outline=document.createElement('div');outline.className='section-flash-overlay';document.body.appendChild(outline);}
document.querySelectorAll('.md-nav--secondary a[href*="#"]').forEach((link)=>{link.addEventListener('click',()=>{const url=new URL(link.href,window.location.href);if(url.pathname!==window.location.pathname||!url.hash){return;}
const heading=document.getElementById(decodeURIComponent(url.hash.slice(1)),);if(!heading||!content.contains(heading)){return;}
const level=Number(heading.tagName.slice(1));if(!Number.isInteger(level)||level<1||level>6){return;}
const section=[heading];let sibling=heading.nextElementSibling;while(sibling){if(sibling.matches('.md-source-file, .md-content__button, .footnote')||(/^H[1-6]$/.test(sibling.tagName)&&Number(sibling.tagName.slice(1))<=level)){break;}
section.push(sibling);sibling=sibling.nextElementSibling;}
const paddingYtop=3;const paddingYbottom=5;const paddingX=10;const flash=()=>{const start=section[0].getBoundingClientRect();const end=section[section.length-1].getBoundingClientRect();outline.style.top=`${start.top - paddingYtop}px`;outline.style.left=`${start.left - paddingX}px`;outline.style.width=`${start.width + paddingX * 2}px`;outline.style.height=`${end.bottom - start.top + paddingYbottom * 2}px`;outline.classList.remove('is-visible');void outline.offsetWidth;outline.classList.add('is-visible');};clearTimeout(scrollFallback);window.removeEventListener('scrollend',onScrollEnd);let flashed=false;function finishScroll(){if(flashed){return;}
flashed=true;clearTimeout(scrollFallback);window.removeEventListener('scrollend',onScrollEnd);flash();}
function onScrollEnd(){finishScroll();}
if('onscrollend'in window){window.addEventListener('scrollend',onScrollEnd);scrollFallback=setTimeout(finishScroll,1500);}else{scrollFallback=setTimeout(finishScroll,700);}});});});